using System;
using System.Linq;
using Game.Areas;
using Game.Tools;
using Game.Prefabs;
using Unity.Mathematics;
using MW.EditorTools.Modules.BulldozerRecovery;
internal static class AreaMoveChecks {
internal static int Run(){int checks=0;void Check(bool v,string name){if(!v)throw new Exception("Area move: "+name);checks++;}
var nodes=new[]{new Node{m_Position=new float3(0,2,0)},new Node{m_Position=new float3(4,2,0)},new Node{m_Position=new float3(0,2,4)}};
var local=nodes.Select(n=>new LocalNodeCache{m_Position=n.m_Position,m_ParentMesh=-1}).ToArray();
var before=new StandaloneAreaData((AreaFlags)1,nodes,local);var moved=nodes.ToArray();moved[0].m_Position.x+=2;
var after=new StandaloneAreaData(before.Flags,moved,local);
Check(AreaMovePolicy.Shape(before,after),"existing vertex may move without topology change");
Check(!before.Matches(after),"moved geometry differs from original");
Check(AreaMovePolicy.Shape(before,before)&&before.Matches(before),"unchanged geometry remains a no-op");
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData((AreaFlags)2,moved,local)),"flags cannot change");
var four=nodes.Concat(new[]{new Node{m_Position=new float3(4,2,4)}}).ToArray();
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData(before.Flags,four,null)),"vertex insertion refused");
var reparent=local.ToArray();reparent[1].m_ParentMesh=3;
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData(before.Flags,moved,reparent)),"parent mesh change refused");
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData(before.Flags,moved,null)),"cache removal refused");
var unbound=new StandaloneAreaData(before.Flags,nodes,null);
Check(AreaMovePolicy.Shape(unbound,new StandaloneAreaData(before.Flags,nodes,local),true),"native standalone cache addition at world positions accepted");
Check(!AreaMovePolicy.Shape(unbound,new StandaloneAreaData(before.Flags,nodes,reparent),true),"added cache cannot attach to a parent mesh");
var wrong=local.ToArray();wrong[0].m_Position.x++;
Check(!AreaMovePolicy.Shape(unbound,new StandaloneAreaData(before.Flags,nodes,wrong),true),"added cache must agree with world geometry");
Check(!AreaMovePolicy.Shape(unbound,before),"bound path cannot assume standalone cache semantics");
Check(!AreaMovePolicy.Shape(null,before),"missing before-image refused");
foreach(var state in new[]{1,2})Check(AreaMovePolicy.Commit(true,true,true,state),"native create/modify commit accepted");
foreach(var state in new[]{0,3,99})Check(!AreaMovePolicy.Commit(true,true,true,state),"default/remove/unknown mode refused");
Check(!AreaMovePolicy.Commit(false,true,true,2),"native denial refused");Check(!AreaMovePolicy.Commit(true,false,true,2),"preview refused");Check(!AreaMovePolicy.Commit(true,true,false,1),"generator refused");
var prefab=(AreaPrefab)System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(typeof(SurfacePrefab));
var row=new ObjectSubAreaInfo{m_AreaPrefab=prefab,m_NodePositions=local.Select(n=>n.m_Position).ToArray()};
Check(AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{local}),"source geometry and references match native cache");
Check(!AreaMovePolicy.Sources(new[]{row,row},new[]{prefab,prefab},new[]{local,local}),"duplicate source placement ambiguous");
Check(!AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{wrong}),"stale source geometry refused");
row.m_ParentMeshes=new[]{-1,3,-1};Check(!AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{local}),"source parent meshes must agree");
Check(!AreaMovePolicy.Sources(null,new[]{prefab},new[]{local}),"absent source list refused");
var expand=new Expand();expand.m_Offset.x=1;var expanded=expand;expanded.m_Offset.x=2;
Check(AreaMovePolicy.ExpansionShape(new[]{expand},new[]{expanded}),"derived expansion offsets may change with a moved vertex");
Check(!AreaMovePolicy.ExpansionShape(new[]{expand},Array.Empty<Expand>()),"expansion topology change refused");
expanded.m_Offset.x=float.NaN;Check(!AreaMovePolicy.ExpansionShape(new[]{expand},new[]{expanded}),"nonfinite expansion refused");
var translated=new float3(123,7,-42);var rotation=quaternion.RotateY(.7f);
var originalLocal=local.Select(n=>n.m_Position).ToArray();
var worldNodes=originalLocal.Select(p=>new Node{m_Position=math.mul(rotation,p)+translated}).ToArray();
worldNodes[0].m_Position+=math.mul(rotation,new float3(2,0,0));
var saved=AreaMovePolicy.SavedPositions(worldNodes,local,translated,rotation);
Check(math.lengthsq(saved[0]-new float3(2,2,0))<1e-8f,"moved world node serialized in owner space instead of stale cache");
Check(saved[1].Equals(local[1].m_Position)&&saved[2].Equals(local[2].m_Position),"nearby unchanged vertices retain exact cache values");
row.m_ParentMeshes=null;row.m_NodePositions=saved;
Check(AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{local},new[]{saved}),"saved source agrees with native projected geometry despite old cache");
Check(!AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{local}),"old cache-only validator rejects legitimate moved descriptor");
row.m_NodePositions=originalLocal;
Check(!AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{local},new[]{saved}),"stale source descriptor cannot match moved world geometry");
Check(AreaMovePolicy.SavedPositions(worldNodes,null,translated,rotation)==null,"missing local attachments refused");
Check(AreaMovePolicy.SavedPositions(worldNodes,Array.Empty<LocalNodeCache>(),translated,rotation)==null,"cache topology mismatch refused");
var closeNodes=nodes.ToArray();closeNodes[0].m_Position.x=.009f;
Check(AreaMovePolicy.SavedPositions(closeNodes,local,float3.zero,quaternion.identity)[0].Equals(local[0].m_Position),"native cache threshold snaps nearby computed coordinate");
closeNodes[0].m_Position.x=.01f;
Check(AreaMovePolicy.SavedPositions(closeNodes,local,float3.zero,quaternion.identity)[0].Equals(closeNodes[0].m_Position),"native exact threshold keeps computed coordinate");
Check(!AreaMovePolicy.Sources(new[]{row},new[]{prefab},new[]{local},new float3[][]{null}),"missing projected source positions refused");
var firstMoveCache=local.ToArray();var firstMoveNodes=nodes.ToArray();firstMoveNodes[0].m_Position.x=2;
var firstMoveSaved=AreaMovePolicy.SavedPositions(firstMoveNodes,firstMoveCache,float3.zero,quaternion.identity);
var regenerated=firstMoveCache.ToArray();for(int i=0;i<regenerated.Length;i++)regenerated[i].m_Position=firstMoveSaved[i];
Check(AreaMovePolicy.RegeneratedCache(firstMoveCache,regenerated,firstMoveSaved),"two-move Undo recognizes cache regenerated from saved first-move nodes");
Check(firstMoveCache[0].m_Position.x==0&&firstMoveNodes[0].m_Position.x==2,"original cache and retained first-move geometry stay detached and unchanged");
var badRegenerated=regenerated.ToArray();badRegenerated[0].m_Position.x+=.1f;
Check(!AreaMovePolicy.RegeneratedCache(firstMoveCache,badRegenerated,firstMoveSaved),"unexplained cache coordinates refused");
badRegenerated=regenerated.ToArray();badRegenerated[0].m_ParentMesh=3;
Check(!AreaMovePolicy.RegeneratedCache(firstMoveCache,badRegenerated,firstMoveSaved),"regeneration cannot change attachment");
badRegenerated=regenerated.ToArray();badRegenerated[0].m_Position.x=float.NaN;
Check(!AreaMovePolicy.RegeneratedCache(firstMoveCache,badRegenerated,firstMoveSaved),"nonfinite regenerated coordinates refused");
Check(!AreaMovePolicy.RegeneratedCache(firstMoveCache,Array.Empty<LocalNodeCache>(),firstMoveSaved),"regenerated topology change refused");
Check(!AreaMovePolicy.RegeneratedCache(firstMoveCache,regenerated,null),"missing serialized geometry refused");
Check(AreaMovePolicy.RegeneratedCache(local,local,local.Select(n=>n.m_Position).ToArray()),"unchanged cache remains exact");
Check(AreaMovePolicy.ShapeDifference(before,new StandaloneAreaData(before.Flags,moved,reparent)).Contains("parentMesh=-1 -> 3"),"snap diagnostic identifies changed attachment and node");
Check(AreaMovePolicy.ShapeDifference(before,new StandaloneAreaData((AreaFlags)2,moved,local)).Contains("flags="),"snap diagnostic identifies changed polygon flags");
Check(AreaMovePolicy.ShapeDifference(before,new StandaloneAreaData(before.Flags,four,null)).Contains("vertices=3 -> 4"),"snap diagnostic distinguishes node insertion");
Check(AreaMovePolicy.ShapeDifference(before,unbound).Contains("cache="),"snap diagnostic identifies cache removal");
Check(AreaMovePolicy.ShapeDifference(before,before)=="geometry shape unchanged","metadata rejection distinguished from geometry shape");
Check(AreaMovePolicy.ShapeDifference(null,before)=="missing geometry image","missing snapshot diagnosis safe");
var snappedLocal=local.ToArray();snappedLocal[1].m_ParentMesh=0;
var snapped=new StandaloneAreaData(before.Flags,moved,snappedLocal);
Check(AreaMovePolicy.Shape(before,snapped,false,true),"bound native -1 to 0 surface snap may be captured with full source checks");
Check(AreaMovePolicy.Shape(snapped,before,false,true),"bound detach from native surface snap may be captured");
Check(!AreaMovePolicy.Shape(before,snapped),"default path still preserves attachments");
Check(!AreaMovePolicy.Shape(before,snapped,true,true),"standalone path cannot enable bound snap exception");
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData(before.Flags,moved,reparent),false,true),"unproven attachment transition to other mesh remains refused");
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData((AreaFlags)2,moved,snappedLocal),false,true),"snap cannot change polygon flags");
Check(!AreaMovePolicy.Shape(before,new StandaloneAreaData(before.Flags,four,null),false,true),"snap cannot change topology");
Check(!before.Matches(snapped),"exact before/after validation continues distinguishing snapped attachment");
var inserted=nodes.Take(1).Concat(new[]{new Node{m_Position=new float3(2,2,0)}}).Concat(nodes.Skip(1)).ToArray();
var insertedCache=inserted.Select(n=>new LocalNodeCache{m_Position=n.m_Position,m_ParentMesh=-1}).ToArray();
var addedData=new StandaloneAreaData(before.Flags,inserted,insertedCache);
Check(AreaNodeEditPolicy.Shape(before,addedData,true),"bound single-node insertion accepted");
Check(AreaNodeEditPolicy.Shape(addedData,before,true),"bound single-node removal accepted");
Check(AreaNodeEditPolicy.AddedIndex(before,addedData,true)==1,"inserted node index identified uniquely");
Check(AreaNodeEditPolicy.Shape(unbound,new StandaloneAreaData(before.Flags,inserted,null),false),"unbound insertion without cache accepted");
Check(AreaNodeEditPolicy.Shape(unbound,addedData,false),"unbound native world-space cache creation accepted");
var movedAdded=inserted.ToArray();movedAdded[1].m_Position.x=3;
var movedAddedData=new StandaloneAreaData(before.Flags,movedAdded,insertedCache);
Check(AreaNodeEditPolicy.OnlyAddedNodeMoved(addedData,movedAddedData,1,true),"move of inserted node qualifies for combination");
Check(!AreaNodeEditPolicy.OnlyAddedNodeMoved(addedData,movedAddedData,0,true),"moving another node cannot combine");
movedAdded[2].m_Position.x+=1;
Check(!AreaNodeEditPolicy.OnlyAddedNodeMoved(addedData,new StandaloneAreaData(before.Flags,movedAdded,insertedCache),1,true),"multiple moved nodes cannot combine");
Check(!AreaNodeEditPolicy.OnlyAddedNodeMoved(addedData,addedData,1,true),"no-op does not create combined move");
Check(!AreaNodeEditPolicy.OnlyAddedNodeMoved(addedData,movedAddedData,-1,true),"invalid added index refused");
Check(!AreaNodeEditPolicy.Shape(before,new StandaloneAreaData(before.Flags,movedAdded,insertedCache),true),"insertion plus unrelated moved node refused");
var duplicate=nodes.Take(1).Concat(new[]{nodes[0]}).Concat(nodes.Skip(1)).ToArray();
Check(!AreaNodeEditPolicy.Shape(unbound,new StandaloneAreaData(before.Flags,duplicate,null),false),"ambiguous duplicate insertion refused");
Check(AreaNodeEditPolicy.Action(before,addedData)=="node addition"&&AreaNodeEditPolicy.Action(addedData,before)=="node deletion","topology actions labelled accurately");
Check(AreaNodeEditPolicy.Commit(true,true,true,3,true),"native Cancel Remove completion accepted");
Check(!AreaNodeEditPolicy.Commit(true,true,true,3,false),"Apply Remove cancellation cannot become deletion");
Check(!AreaNodeEditPolicy.Commit(false,true,true,3,true),"native denied removal refused");
Check(!AreaNodeEditPolicy.Commit(true,false,true,3,true),"removal preview refused");
Check(!AreaNodeEditPolicy.Commit(true,true,false,3,true),"generator removal refused");
Check(!AreaNodeEditPolicy.Shape(before,new StandaloneAreaData((AreaFlags)2,inserted,insertedCache),true),"insertion cannot change polygon flags");
Check(AreaNodeEditPolicy.AddedIndex(addedData,before,true)==-1,"deletion cannot claim an added node");
Check(!AreaNodeEditPolicy.Shape(before,new StandaloneAreaData(before.Flags,inserted.Concat(new[]{new Node{m_Position=new float3(3,2,0)}}).ToArray(),null),true),"multi-node topology edit refused");
var diagnostics=AreaGeometry.Explain(firstMoveNodes,firstMoveCache,firstMoveNodes,regenerated,firstMoveSaved);
Check(diagnostics.Contains("node[0]")&&diagnostics.Contains("saved="),"restoration diagnostic identifies exact differing cache and saved projection");
var elevated=firstMoveNodes.ToArray();elevated[1].m_Elevation=.01f;
Check(AreaGeometry.Explain(firstMoveNodes,firstMoveCache,elevated,firstMoveCache).Contains("elevation=0/0.01"),"restoration diagnostic exposes finite elevation mismatch");
Check(AreaGeometry.Explain(nodes,local,inserted,insertedCache).Contains("nodes=3/4"),"restoration diagnostic exposes count mismatch");
Check(AreaGeometry.Explain(nodes,null,nodes,local).Contains("missing"),"restoration diagnostic tolerates absent cache");
return checks;
}}
